CREATE TABLE public.departments (id text PRIMARY KEY, organization_id text NOT NULL DEFAULT 'quantera', name text NOT NULL, manager_id text);
GRANT SELECT ON public.departments TO authenticated; GRANT ALL ON public.departments TO service_role;
ALTER TABLE public.departments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.employees (id text PRIMARY KEY, organization_id text NOT NULL DEFAULT 'quantera', name text NOT NULL, email text NOT NULL UNIQUE, title text NOT NULL, department_id text NOT NULL REFERENCES public.departments(id), manager_id text REFERENCES public.employees(id), access_role text NOT NULL CHECK(access_role IN ('Founder','Manager','Employee')), active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.employees TO authenticated; GRANT ALL ON public.employees TO service_role;
ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, employee_id text NOT NULL UNIQUE REFERENCES public.employees(id), organization_id text NOT NULL DEFAULT 'quantera', display_name text NOT NULL, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('founder','manager','employee','finance')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.projects (id text PRIMARY KEY, organization_id text NOT NULL DEFAULT 'quantera', data jsonb NOT NULL);
GRANT SELECT ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_departments (project_id text REFERENCES public.projects(id) ON DELETE CASCADE, department_id text REFERENCES public.departments(id), PRIMARY KEY(project_id,department_id));
GRANT SELECT ON public.project_departments TO authenticated; GRANT ALL ON public.project_departments TO service_role;
ALTER TABLE public.project_departments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.access_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id text NOT NULL DEFAULT 'quantera', user_id uuid NOT NULL, department_id text REFERENCES public.departments(id), project_id text REFERENCES public.projects(id), reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','revoked')), decision_note text NOT NULL DEFAULT '', decided_by uuid, created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, CHECK((department_id IS NOT NULL)::int + (project_id IS NOT NULL)::int = 1));
GRANT SELECT,INSERT ON public.access_requests TO authenticated; GRANT ALL ON public.access_requests TO service_role;
ALTER TABLE public.access_requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.access_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id text NOT NULL DEFAULT 'quantera', user_id uuid NOT NULL, department_id text REFERENCES public.departments(id), project_id text REFERENCES public.projects(id), request_id uuid REFERENCES public.access_requests(id), granted_by uuid NOT NULL, revoked_at timestamptz, CHECK((department_id IS NOT NULL)::int + (project_id IS NOT NULL)::int = 1));
GRANT SELECT ON public.access_grants TO authenticated; GRANT ALL ON public.access_grants TO service_role;
ALTER TABLE public.access_grants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.budgets (id text PRIMARY KEY, organization_id text NOT NULL DEFAULT 'quantera', department_id text NOT NULL REFERENCES public.departments(id), project_id text REFERENCES public.projects(id), data jsonb NOT NULL);
GRANT SELECT ON public.budgets TO authenticated; GRANT ALL ON public.budgets TO service_role;
ALTER TABLE public.budgets ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.expenses (id text PRIMARY KEY, organization_id text NOT NULL DEFAULT 'quantera', employee_id text NOT NULL REFERENCES public.employees(id), department_id text NOT NULL REFERENCES public.departments(id), project_id text REFERENCES public.projects(id), approval_status text NOT NULL DEFAULT 'pending' CHECK(approval_status IN ('pending','approved','rejected','changes_requested')), data jsonb NOT NULL);
GRANT SELECT ON public.expenses TO authenticated; GRANT ALL ON public.expenses TO service_role;
ALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.receipts (id text PRIMARY KEY, organization_id text NOT NULL DEFAULT 'quantera', expense_id text NOT NULL REFERENCES public.expenses(id), storage_path text NOT NULL, data jsonb NOT NULL);
GRANT SELECT ON public.receipts TO authenticated; GRANT ALL ON public.receipts TO service_role;
ALTER TABLE public.receipts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.approvals (id text PRIMARY KEY, expense_id text NOT NULL REFERENCES public.expenses(id), data jsonb NOT NULL);
GRANT SELECT ON public.approvals TO authenticated; GRANT ALL ON public.approvals TO service_role;
ALTER TABLE public.approvals ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reimbursements (id text PRIMARY KEY, organization_id text NOT NULL DEFAULT 'quantera', expense_id text NOT NULL UNIQUE REFERENCES public.expenses(id), employee_id text NOT NULL REFERENCES public.employees(id), status text NOT NULL DEFAULT 'awaiting_authorization' CHECK(status IN ('awaiting_authorization','queued')), data jsonb NOT NULL);
GRANT SELECT ON public.reimbursements TO authenticated; GRANT ALL ON public.reimbursements TO service_role;
ALTER TABLE public.reimbursements ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.notifications (id text PRIMARY KEY, user_id uuid NOT NULL, data jsonb NOT NULL);
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.approval_policies (organization_id text PRIMARY KEY, data jsonb NOT NULL);
GRANT SELECT ON public.approval_policies TO authenticated; GRANT ALL ON public.approval_policies TO service_role;
ALTER TABLE public.approval_policies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id text NOT NULL DEFAULT 'quantera', actor_id uuid NOT NULL, action text NOT NULL, target_id text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_log TO authenticated; GRANT ALL ON public.audit_log TO service_role;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.current_employee() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.employee_id FROM public.profiles p JOIN public.employees e ON e.id=p.employee_id JOIN auth.users u ON u.id=p.id WHERE p.id=auth.uid() AND p.organization_id='quantera' AND e.organization_id='quantera' AND e.active AND u.email_confirmed_at IS NOT NULL AND lower(u.email)=lower(e.email) $$;
CREATE FUNCTION public.has_role(_user_id uuid, _role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id=auth.uid() AND public.current_employee() IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.can_department(_department text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.current_employee() IS NOT NULL AND (public.has_role(auth.uid(),'founder') OR EXISTS(SELECT 1 FROM public.employees WHERE id=public.current_employee() AND department_id=_department) OR EXISTS(SELECT 1 FROM public.access_grants WHERE user_id=auth.uid() AND department_id=_department AND revoked_at IS NULL)) $$;
CREATE FUNCTION public.can_project(_project text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.current_employee() IS NOT NULL AND (public.has_role(auth.uid(),'founder') OR EXISTS(SELECT 1 FROM public.project_departments pd JOIN public.employees e ON e.department_id=pd.department_id WHERE e.id=public.current_employee() AND pd.project_id=_project) OR EXISTS(SELECT 1 FROM public.access_grants WHERE user_id=auth.uid() AND project_id=_project AND revoked_at IS NULL)) $$;
CREATE FUNCTION public.can_expense(_expense text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.current_employee() IS NOT NULL AND EXISTS(SELECT 1 FROM public.expenses x WHERE x.id=_expense AND x.organization_id='quantera' AND (public.has_role(auth.uid(),'founder') OR x.employee_id=public.current_employee() OR (public.has_role(auth.uid(),'manager') AND EXISTS(SELECT 1 FROM public.departments WHERE id=x.department_id AND manager_id=public.current_employee())) OR EXISTS(SELECT 1 FROM public.access_grants g WHERE g.user_id=auth.uid() AND g.department_id=x.department_id AND g.revoked_at IS NULL))) $$;
REVOKE ALL ON FUNCTION public.current_employee(), public.has_role(uuid,text), public.can_department(text), public.can_project(text), public.can_expense(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.current_employee(), public.has_role(uuid,text), public.can_department(text), public.can_project(text), public.can_expense(text) TO authenticated,service_role;
CREATE POLICY departments_read ON public.departments FOR SELECT TO authenticated USING(organization_id='quantera' AND public.current_employee() IS NOT NULL);
CREATE POLICY employees_read ON public.employees FOR SELECT TO authenticated USING(organization_id='quantera' AND public.current_employee() IS NOT NULL);
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY projects_read ON public.projects FOR SELECT TO authenticated USING(organization_id='quantera' AND public.can_project(id));
CREATE POLICY project_departments_read ON public.project_departments FOR SELECT TO authenticated USING(public.can_project(project_id));
CREATE POLICY budgets_read ON public.budgets FOR SELECT TO authenticated USING(organization_id='quantera' AND (public.can_department(department_id) OR (project_id IS NOT NULL AND public.can_project(project_id))));
CREATE POLICY expenses_read ON public.expenses FOR SELECT TO authenticated USING(public.can_expense(id));
CREATE POLICY receipts_read ON public.receipts FOR SELECT TO authenticated USING(organization_id='quantera' AND public.can_expense(expense_id));
CREATE POLICY approvals_read ON public.approvals FOR SELECT TO authenticated USING(public.can_expense(expense_id));
CREATE POLICY reimbursements_read ON public.reimbursements FOR SELECT TO authenticated USING(organization_id='quantera' AND (public.can_expense(expense_id) OR public.has_role(auth.uid(),'finance')));
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.current_employee() IS NOT NULL);
CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid() AND public.current_employee() IS NOT NULL) WITH CHECK(user_id=auth.uid());
CREATE POLICY policies_read ON public.approval_policies FOR SELECT TO authenticated USING(organization_id='quantera' AND public.current_employee() IS NOT NULL);
CREATE POLICY requests_read ON public.access_requests FOR SELECT TO authenticated USING(organization_id='quantera' AND public.current_employee() IS NOT NULL AND (user_id=auth.uid() OR public.has_role(auth.uid(),'founder')));
CREATE POLICY requests_insert ON public.access_requests FOR INSERT TO authenticated WITH CHECK(organization_id='quantera' AND public.current_employee() IS NOT NULL AND user_id=auth.uid() AND status='pending' AND decided_by IS NULL AND decided_at IS NULL AND decision_note='');
CREATE POLICY grants_read ON public.access_grants FOR SELECT TO authenticated USING(organization_id='quantera' AND public.current_employee() IS NOT NULL AND (user_id=auth.uid() OR public.has_role(auth.uid(),'founder')));
CREATE POLICY audit_read ON public.audit_log FOR SELECT TO authenticated USING(organization_id='quantera' AND public.has_role(auth.uid(),'founder'));
CREATE FUNCTION public.sync_employee_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE emp public.employees; BEGIN SELECT * INTO emp FROM public.employees WHERE lower(email)=lower(new.email) AND active AND organization_id='quantera'; IF emp.id IS NOT NULL THEN INSERT INTO public.profiles(id,employee_id,display_name) VALUES(new.id,emp.id,emp.name) ON CONFLICT(id) DO NOTHING; IF new.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,CASE emp.access_role WHEN 'Founder' THEN 'founder' WHEN 'Manager' THEN 'manager' ELSE 'employee' END) ON CONFLICT DO NOTHING; IF emp.id IN ('EMP-001','EMP-003') THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'finance') ON CONFLICT DO NOTHING; END IF; END IF; END IF; RETURN new; END $$;
REVOKE ALL ON FUNCTION public.sync_employee_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER employee_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_employee_profile();
CREATE TRIGGER employee_profile_confirmed AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW WHEN(old.email_confirmed_at IS NULL AND new.email_confirmed_at IS NOT NULL) EXECUTE FUNCTION public.sync_employee_profile();
CREATE INDEX expenses_department_idx ON public.expenses(department_id); CREATE INDEX grants_user_idx ON public.access_grants(user_id); CREATE INDEX profiles_employee_idx ON public.profiles(employee_id);
CREATE FUNCTION public.shared_project_totals() RETURNS TABLE(project_id text,approved_total numeric,pending_total numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,coalesce(sum((x.data->>'amount')::numeric) FILTER(WHERE x.approval_status='approved'),0),coalesce(sum((x.data->>'amount')::numeric) FILTER(WHERE x.approval_status='pending'),0) FROM public.projects p LEFT JOIN public.expenses x ON x.project_id=p.id AND x.organization_id='quantera' WHERE p.organization_id='quantera' AND public.can_project(p.id) GROUP BY p.id $$;
REVOKE ALL ON FUNCTION public.shared_project_totals() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.shared_project_totals() TO authenticated;
